<script lang="ts">import type { Snippet } from 'svelte'; import { getComboboxContext } from './combobox-context.svelte.js'; export interface Props { children: Snippet<[unknown, number]>; } let { children }: Props = $props(); const box = getComboboxContext(); let filtered = $derived(box.sourceItems.filter((item) => box.filter(item, box.inputValue)));</script>{#each filtered as item, index (item)}{@render children(item, index)}{/each}
